  (1466, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school","organisation":"Harwich School","detail":"He grew up in Harwich and attended Harwich School.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"education","start":null,"end":null,"title":"Officer training","organisation":"Britannia Royal Naval College","detail":"He attended the Britannia Royal Naval College at Dartmouth.","source":{"title":"Politics.co.uk: Andrew Murrison","url":"https://www.politics.co.uk/people/andrew-murrison/"}},{"phase":"education","start":"1984","end":"1984","title":"MB ChB in medicine","organisation":"University of Bristol","detail":"He qualified as a doctor from the University of Bristol medical school with a Royal Navy scholarship.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"education","start":"1995","end":"1995","title":"Doctoral thesis","organisation":null,"detail":"His doctoral thesis was entitled Studies into the Neurological Consequences of Diving, and he was awarded the Gilbert Blane medal.","source":{"title":"About Andrew | The Rt Hon Dr Andrew Murrison MP","url":"https://www.andrewmurrison.co.uk/about-andrew"}},{"phase":"education","start":"1996","end":"1996","title":"Diploma in Public Health","organisation":"Hughes Hall, Cambridge","detail":"He spent a year as a postgraduate student at Hughes Hall and graduated from Cambridge with a Diploma in Public Health.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":null,"end":"2000-10","title":"Medical officer","organisation":"Royal Navy","detail":"He served for 18 years as a medical officer in the Royal Navy and left in October 2000 as a Surgeon Commander.","source":{"title":"GOV.UK: The Rt Hon Dr Andrew Murrison MP","url":"https://www.gov.uk/government/people/andrew-murrison"}},{"phase":"career","start":"1985-08","end":"1985-08","title":"Confirmed in the rank of Surgeon Lieutenant","organisation":"Royal Navy","detail":"He was commissioned into the Medical Branch of the Royal Navy and confirmed as Surgeon Lieutenant on 1 August 1985.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":null,"end":null,"title":"Research registrar","organisation":"Southampton General Hospital","detail":"He worked as a research registrar at Southampton General Hospital during his naval career while qualifying as a general practitioner.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":"1997-12","end":"1997-12","title":"Promoted to Surgeon Commander","organisation":"Royal Navy","detail":"He was promoted to Surgeon Commander on 31 December 1997.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":"2000-10","end":null,"title":"Surgeon Commander, Royal Naval Reserve","organisation":"Royal Naval Reserve","detail":"He entered the Royal Naval Reserve as a Surgeon Commander on 28 October 2000.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":"2000","end":null,"title":"Locum general practitioner","organisation":null,"detail":"From 2000 he worked as a locum general practitioner in Wiltshire.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"career","start":"2000","end":null,"title":"Consultant in occupational health","organisation":"Gloucestershire Royal Hospital","detail":"From 2000 he worked as a consultant in occupational health at Gloucestershire Royal Hospital.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"politics","start":null,"end":null,"title":"Member","organisation":"Bow Group","detail":"He was a member of the Bow Group before entering full time politics.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"politics","start":null,"end":null,"title":"Assistant to Sir Peter Lloyd","organisation":null,"detail":"He worked as an assistant to the Conservative MP Sir Peter Lloyd.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"politics","start":"1999","end":"2000","title":"Assistant to Lord Freeman","organisation":"Conservative Central Office","detail":"He assisted Lord Freeman, whose role at Conservative Central Office was screening potential parliamentary candidates.","source":{"title":"Wikipedia: Andrew Murrison","url":"https://en.wikipedia.org/wiki/Andrew_Murrison"}},{"phase":"politics","start":"2001","end":"2001","title":"Elected MP for Westbury","organisation":"Conservative Party","detail":"He won Westbury for the Conservatives at the 2001 general election.","source":{"title":"2001 General Election: Westbury, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/24427"}}]$bt$::jsonb::text)),
  (1482, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school","organisation":"Glenalmond College","detail":"He was educated at Glenalmond College, an independent school in Perthshire.","source":{"title":"Politics.co.uk: Graham Stuart","url":"https://www.politics.co.uk/people/graham-stuart/"}},{"phase":"education","start":"1982","end":"1985","title":"Philosophy and law (degree not completed)","organisation":"Selwyn College, Cambridge","detail":"He studied philosophy and law at Selwyn College but did not complete his degree, focusing instead on his business producing What's on in Cambridge guides.","source":{"title":"Politics.co.uk: Graham Stuart","url":"https://www.politics.co.uk/people/graham-stuart/"}},{"phase":"career","start":null,"end":null,"title":"Founder, What's On in Cambridge","organisation":null,"detail":"He founded the What's On in Cambridge guide while a student at Cambridge.","source":{"title":"GOV.UK: The Rt Hon Graham Stuart","url":"https://www.gov.uk/government/people/graham-stuart"}},{"phase":"career","start":null,"end":null,"title":"Publisher","organisation":null,"detail":"After university he worked in publishing, and his business expanded to produce food guides, style magazines and magazines about boats and jetskis.","source":{"title":"The Guardian: Graham Stuart: 'You can't drive education like a sports car'","url":"https://www.theguardian.com/education/2013/mar/25/graham-stuart-conservative-education-committee"}},{"phase":"politics","start":null,"end":null,"title":"Chairman","organisation":"Cambridge University Conservative Association","detail":"He chaired the Cambridge University Conservative Association while at Cambridge.","source":{"title":"GOV.UK: The Rt Hon Graham Stuart","url":"https://www.gov.uk/government/people/graham-stuart"}},{"phase":"politics","start":"1998","end":"2004","title":"Councillor, Cherry Hinton ward","organisation":"Cambridge City Council","detail":"He served as a Conservative councillor for the Cherry Hinton ward.","source":{"title":"Politics.co.uk: Graham Stuart","url":"https://www.politics.co.uk/people/graham-stuart/"}},{"phase":"politics","start":null,"end":null,"title":"School governor","organisation":null,"detail":"As a council representative he became governor of a school described as failing.","source":{"title":"The Guardian: Graham Stuart: 'You can't drive education like a sports car'","url":"https://www.theguardian.com/education/2013/mar/25/graham-stuart-conservative-education-committee"}},{"phase":"politics","start":"2001","end":"2001","title":"Conservative candidate for Cambridge","organisation":"Conservative Party","detail":"He received 9,829 votes at the 2001 general election and the seat was won by Anne Campbell of Labour.","source":{"title":"2001 General Election: Cambridge, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/23900"}},{"phase":"politics","start":"2002","end":"2002","title":"Reelected councillor, Cherry Hinton ward","organisation":"Cambridge City Council","detail":"He was reelected for Cherry Hinton at the 2002 Cambridge City Council election.","source":{"title":"Wikipedia: 2002 Cambridge City Council election","url":"https://en.wikipedia.org/wiki/2002_Cambridge_City_Council_election"}},{"phase":"politics","start":"2005","end":"2005","title":"Elected MP for Beverley and Holderness","organisation":"Conservative Party","detail":"He won Beverley and Holderness for the Conservatives at the 2005 general election.","source":{"title":"2005 General Election: Beverley and Holderness, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/24491"}}]$bt$::jsonb::text)),
  (1489, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school","organisation":"Tom Hood School","detail":"She was educated at Tom Hood School in Leytonstone.","source":{"title":"Politics.co.uk: Dawn Butler","url":"https://www.politics.co.uk/people/dawn-butler/"}},{"phase":"education","start":null,"end":null,"title":"Further education","organisation":"Waltham Forest College","detail":"She attended Waltham Forest College after school.","source":{"title":"Politics.co.uk: Dawn Butler","url":"https://www.politics.co.uk/people/dawn-butler/"}},{"phase":"education","start":null,"end":null,"title":"Did not attend university","organisation":null,"detail":"She did not go to university.","source":{"title":"The Guardian: Dawn Butler: 'It is shocking, the disrespect for Black women in the Commons'","url":"https://www.theguardian.com/politics/2023/aug/14/dawn-butler-mp-it-is-shocking-the-disrespect-for-black-women-in-the-commons"}},{"phase":"career","start":null,"end":null,"title":"Computer programmer","organisation":null,"detail":"After finishing college she worked as a computer programmer for a City firm.","source":{"title":"The Guardian: Dawn Butler: 'It is shocking, the disrespect for Black women in the Commons'","url":"https://www.theguardian.com/politics/2023/aug/14/dawn-butler-mp-it-is-shocking-the-disrespect-for-black-women-in-the-commons"}},{"phase":"career","start":null,"end":null,"title":"Civil servant","organisation":null,"detail":"She worked as a civil servant before becoming a trade unionist.","source":{"title":"The Guardian: Dawn Butler: 'It is shocking, the disrespect for Black women in the Commons'","url":"https://www.theguardian.com/politics/2023/aug/14/dawn-butler-mp-it-is-shocking-the-disrespect-for-black-women-in-the-commons"}},{"phase":"career","start":null,"end":null,"title":"Employment service trainer","organisation":null,"detail":"She worked as an employment service trainer after working as a computer programmer.","source":{"title":"The Guardian: Labour's Dawn Butler: 'People threatened to kill me. I've been attacked on the tube'","url":"https://www.theguardian.com/politics/2020/aug/04/labour-dawn-butler-people-threatened-to-kill-me-ive-been-attacked-on-the-tube"}},{"phase":"career","start":null,"end":null,"title":"Trade union officer","organisation":"Public and Commercial Services Union","detail":"She worked for the Public and Commercial Services Union before the GMB.","source":{"title":"The Guardian: Labour's Dawn Butler: 'People threatened to kill me. I've been attacked on the tube'","url":"https://www.theguardian.com/politics/2020/aug/04/labour-dawn-butler-people-threatened-to-kill-me-ive-been-attacked-on-the-tube"}},{"phase":"career","start":null,"end":null,"title":"Officer, including national race and equality officer","organisation":"GMB","detail":"She worked as an officer for the GMB trade union, including as a national officer responsible for race and equality issues.","source":{"title":"Politics.co.uk: Dawn Butler","url":"https://www.politics.co.uk/people/dawn-butler/"}},{"phase":"career","start":"2005-03","end":"2005-03","title":"Policy officer","organisation":"GMB","detail":"She was described as a GMB union policy officer when shortlisted for Brent South in March 2005.","source":{"title":"The Guardian: All black Labour shortlist in Brent","url":"https://www.theguardian.com/politics/2005/mar/21/uk.race1"}},{"phase":"career","start":null,"end":null,"title":"Adviser to the Mayor of London","organisation":null,"detail":"She advised the then Mayor of London, Ken Livingstone, on employment and social issues.","source":{"title":"Politics.co.uk: Dawn Butler","url":"https://www.politics.co.uk/people/dawn-butler/"}},{"phase":"politics","start":"2003","end":null,"title":"Sought Labour selection for Hackney South and Shoreditch","organisation":"Labour Party","detail":"She was asked in 2003 to seek selection and lost the selection to Meg Hillier.","source":{"title":"The Guardian: Dawn Butler: 'It is shocking, the disrespect for Black women in the Commons'","url":"https://www.theguardian.com/politics/2023/aug/14/dawn-butler-mp-it-is-shocking-the-disrespect-for-black-women-in-the-commons"}},{"phase":"politics","start":"2005-02","end":"2005-02","title":"Sought Labour selection for West Ham","organisation":"Labour Party","detail":"She lost the West Ham selection to Lyn Brown by four votes.","source":{"title":"The Guardian: Dawn Butler: 'It is shocking, the disrespect for Black women in the Commons'","url":"https://www.theguardian.com/politics/2023/aug/14/dawn-butler-mp-it-is-shocking-the-disrespect-for-black-women-in-the-commons"}},{"phase":"politics","start":"2005-03","end":"2005-03","title":"Shortlisted for Labour selection in Brent South","organisation":"Labour Party","detail":"She was one of four candidates on an all minority shortlist to replace Paul Boateng.","source":{"title":"The Guardian: All black Labour shortlist in Brent","url":"https://www.theguardian.com/politics/2005/mar/21/uk.race1"}},{"phase":"politics","start":"2005","end":"2005","title":"Selected as Labour candidate for Brent South","organisation":"Labour Party","detail":"She won the Brent South selection a month after the West Ham contest.","source":{"title":"The Guardian: Labour's Dawn Butler: 'People threatened to kill me. I've been attacked on the tube'","url":"https://www.theguardian.com/politics/2020/aug/04/labour-dawn-butler-people-threatened-to-kill-me-ive-been-attacked-on-the-tube"}},{"phase":"politics","start":"2005","end":"2005","title":"Elected MP for Brent South","organisation":"Labour Party","detail":"She won Brent South for Labour at the 2005 general election.","source":{"title":"2005 General Election: Brent South, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/24532"}},{"phase":"politics","start":"2010","end":"2010","title":"Labour candidate for Brent Central","organisation":"Labour Party","detail":"She received 18,681 votes and lost to Sarah Teather of the Liberal Democrats.","source":{"title":"2010 General Election: Brent Central, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/25176"}},{"phase":"career","start":"2010","end":"2015","title":"Designer of learning programmes","organisation":null,"detail":"Between leaving Parliament in 2010 and returning in 2015 she designed learning programmes for companies.","source":{"title":"The Guardian: Labour's Dawn Butler: 'People threatened to kill me. I've been attacked on the tube'","url":"https://www.theguardian.com/politics/2020/aug/04/labour-dawn-butler-people-threatened-to-kill-me-ive-been-attacked-on-the-tube"}},{"phase":"politics","start":"2013-12","end":"2013-12","title":"Selected as Labour candidate for Brent Central","organisation":"Labour Party","detail":"She was selected to contest Brent Central at the next general election.","source":{"title":"Evening Standard: Labour selects ex MP who quit amid expenses scandal to fight for Brent Central","url":"https://www.standard.co.uk/news/politics/labour-selects-ex-mp-who-quit-amid-expenses-scandal-to-fight-for-brent-central-8993059.html"}},{"phase":"politics","start":"2015","end":"2015","title":"Elected MP for Brent Central","organisation":"Labour Party","detail":"She won Brent Central for Labour at the 2015 general election.","source":{"title":"2015 General Election: Brent Central, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/25826"}}]$bt$::jsonb::text)),
  (1508, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school","organisation":"King's College, Taunton","detail":"He attended King's College, Taunton.","source":{"title":"Politics.co.uk: Geoffrey Cox","url":"https://www.politics.co.uk/people/geoffrey-cox/"}},{"phase":"education","start":null,"end":null,"title":"Law and classics","organisation":"Downing College, Cambridge","detail":"He studied law and classics at Downing College, Cambridge.","source":{"title":"Politics.co.uk: Geoffrey Cox","url":"https://www.politics.co.uk/people/geoffrey-cox/"}},{"phase":"career","start":"1982","end":"1982","title":"Called to the Bar","organisation":"Middle Temple","detail":"He was called to the Bar at the Middle Temple and began practice as a barrister.","source":{"title":"Wikipedia: Geoffrey Cox (British politician)","url":"https://en.wikipedia.org/wiki/Geoffrey_Cox_(British_politician)"}},{"phase":"career","start":"1982","end":null,"title":"Barrister","organisation":null,"detail":"He was called to the bar in 1982 and pursued a career as a barrister.","source":{"title":"Politics.co.uk: Geoffrey Cox","url":"https://www.politics.co.uk/people/geoffrey-cox/"}},{"phase":"career","start":"1992","end":null,"title":"Founder and later head of chambers","organisation":"Thomas More Chambers","detail":"He jointly founded Thomas More Chambers in 1992 and later served as its head of chambers.","source":{"title":"Politics.co.uk: Geoffrey Cox","url":"https://www.politics.co.uk/people/geoffrey-cox/"}},{"phase":"career","start":null,"end":null,"title":"Standing counsel to the government of Mauritius","organisation":null,"detail":"He was standing counsel to the government of Mauritius for a time.","source":{"title":"Politics.co.uk: Geoffrey Cox","url":"https://www.politics.co.uk/people/geoffrey-cox/"}},{"phase":"career","start":"2003","end":"2003","title":"Appointed Queen's Counsel","organisation":null,"detail":"He was appointed Queen's Counsel in 2003.","source":{"title":