  (1512, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school","organisation":"Lockerbie Academy","detail":"He attended Lockerbie Academy.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"education","start":null,"end":null,"title":"MA in law and Diploma in Legal Practice","organisation":"University of Edinburgh","detail":"He studied law at the University of Edinburgh, gaining an MA and a Diploma in Legal Practice.","source":{"title":"Politics.co.uk: David Mundell","url":"https://www.politics.co.uk/people/david-mundell/"}},{"phase":"education","start":null,"end":null,"title":"MBA","organisation":"University of Strathclyde Business School","detail":"He received an MBA from the University of Strathclyde Business School.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"career","start":null,"end":null,"title":"Solicitor","organisation":null,"detail":"He worked as a solicitor before joining BT.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"career","start":null,"end":null,"title":"Member, Law Society and Writers to the Signet","organisation":null,"detail":"He is a member of the Law Society and the Writers to the Signet.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"career","start":"1991","end":null,"title":"Group Legal Adviser for Scotland","organisation":"BT","detail":"He joined BT as Group Legal Advisor for Scotland in 1991.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"career","start":null,"end":null,"title":"Head of National Affairs","organisation":"BT Scotland","detail":"He became head of national affairs at BT Scotland and stayed with BT until becoming an MSP.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"politics","start":null,"end":null,"title":"Joined the Conservative Party","organisation":"Conservative Party","detail":"He joined the Conservative Party aged 14.","source":{"title":"Politics.co.uk: David Mundell","url":"https://www.politics.co.uk/people/david-mundell/"}},{"phase":"politics","start":"1981","end":"1981","title":"Joined the Social Democratic Party","organisation":"Social Democratic Party","detail":"He moved from the Young Conservatives to the SDP while at university.","source":{"title":"Wikipedia: David Mundell","url":"https://en.wikipedia.org/wiki/David_Mundell"}},{"phase":"politics","start":"1984","end":"1984","title":"Elected councillor for Dryfe ward","organisation":"Annandale and Eskdale District Council","detail":"He was elected for the SDP in Dryfe ward, gaining the seat from an independent.","source":{"title":"The Scottish District Elections 1984 (Bochel and Denver), p. 82","url":"https://www.electionscentre.co.uk/wp-content/uploads/2015/10/Scottish-District-Elections-1984.pdf"}},{"phase":"politics","start":"1984","end":"1986","title":"SDP councillor","organisation":"Annandale and Eskdale District Council","detail":"He served as an SDP councillor while a student.","source":{"title":"Politics.co.uk: David Mundell","url":"https://www.politics.co.uk/people/david-mundell/"}},{"phase":"politics","start":"1986","end":"1986","title":"Elected councillor for Mid Annandale ward","organisation":"Dumfries and Galloway Regional Council","detail":"He won Mid Annandale for the SDP with 1,132 votes, gaining the seat from an independent.","source":{"title":"Scottish Regional Elections 1986 (Bochel and Denver), p. 33","url":"https://www.electionscentre.co.uk/wp-content/uploads/2015/10/Scottish-Regional-Elections-1986.pdf"}},{"phase":"politics","start":"1986","end":"1987","title":"SDP councillor","organisation":"Dumfries and Galloway Regional Council","detail":"He served as an SDP councillor on the regional council while a student.","source":{"title":"Politics.co.uk: David Mundell","url":"https://www.politics.co.uk/people/david-mundell/"}},{"phase":"politics","start":"1988","end":"1988","title":"Rejoined the Conservative Party","organisation":"Conservative Party","detail":"He rejoined the Conservative Party in 1988.","source":{"title":"Politics.co.uk: David Mundell","url":"https://www.politics.co.uk/people/david-mundell/"}},{"phase":"politics","start":"1999","end":"1999","title":"Conservative candidate for Dumfries, Scottish Parliament election","organisation":"Conservative Party","detail":"He stood for the Dumfries constituency at the first Scottish Parliament election.","source":{"title":"Biography | David Mundell MP","url":"https://www.davidmundell.com/biography"}},{"phase":"politics","start":"1999","end":"2005","title":"Member of the Scottish Parliament for the South of Scotland region","organisation":"Scottish Parliament","detail":"He was elected for the South of Scotland region in 1999 and served as an MSP until his election to Westminster in 2005.","source":{"title":"Biography | David Mundell MP","url":"https://www.davidmundell.com/biography"}},{"phase":"politics","start":"2003","end":"2003","title":"Reelected list MSP for the South of Scotland","organisation":"Scottish Parliament","detail":"He was reelected as a list MSP for the South of Scotland in 2003.","source":{"title":"GOV.UK: The Rt Hon David Mundell","url":"https://www.gov.uk/government/people/david-mundell"}},{"phase":"politics","start":"2005","end":"2005","title":"Elected MP for Dumfriesshire, Clydesdale and Tweeddale","organisation":"Conservative Party","detail":"He won Dumfriesshire, Clydesdale and Tweeddale for the Conservatives at the 2005 general election.","source":{"title":"2005 General Election: Dumfriesshire, Clydesdale and Tweeddale, UK General Elections Results","url":"https://api.parliament.uk/uk-general-elections/elections/24631"}}]$bt$::jsonb::text)),
  (1516, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Latymer Upper School","organisation":"Latymer Upper School","detail":"He was educated at Latymer Upper School in Hammersmith.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"education","start":"1979","end":"1982","title":"Read English","organisation":"University of Exeter","detail":"He read English at the University of Exeter between 1979 and 1982.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"education","start":null,"end":null,"title":"Studied law","organisation":"College of Law","detail":"He studied at the College of Law.","source":{"title":"Wikipedia: Andy Slaughter","url":"https://en.wikipedia.org/wiki/Andy_Slaughter"}},{"phase":"education","start":null,"end":null,"title":"Studied law","organisation":"Inns of Court School of Law","detail":"He studied at the Inns of Court School of Law.","source":{"title":"Wikipedia: Andy Slaughter","url":"https://en.wikipedia.org/wiki/Andy_Slaughter"}},{"phase":"education","start":"1993","end":"1993","title":"Called to the bar","organisation":"Middle Temple","detail":"He was called to the bar at Middle Temple in 1993.","source":{"title":"Wikipedia: Andy Slaughter","url":"https://en.wikipedia.org/wiki/Andy_Slaughter"}},{"phase":"career","start":null,"end":null,"title":"Staff member","organisation":"British Safety Council","detail":"In the 1980s he worked for the British Safety Council.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":null,"end":null,"title":"Staff member","organisation":"Hammersmith & Fulham Council","detail":"He then worked for Hammersmith & Fulham Council.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":null,"end":null,"title":"Adviser to Michael Meacher MP","organisation":null,"detail":"He worked as an adviser to Michael Meacher MP, Shadow Secretary for Employment and later Social Security.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":null,"end":null,"title":"Researcher","organisation":"BBC","detail":"He worked as a researcher for the BBC.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":"1993","end":"2005","title":"Barrister","organisation":"Bridewell Chambers","detail":"He practised from Bridewell Chambers in Blackfriars, specialising in personal injury and housing law, and stopped practising when elected as an MP in 2005.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":null,"end":null,"title":"Director","organisation":"Broadway","detail":"He served for twenty years as a director of Broadway (now part of St Mungo's), a local charity for the single homeless.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":null,"end":"2021-01","title":"Trustee","organisation":"Hammersmith & Fulham Law Centre","detail":"He was a trustee of Hammersmith & Fulham Law Centre for over 30 years, stepping down in January 2021.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"career","start":"1994","end":"2020","title":"Governor","organisation":"William Morris Sixth Form","detail":"He helped to establish William Morris Sixth Form in Barons Court in 1994 and was a governor until 2020.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"politics","start":"1983","end":"1983","title":"Joined the Labour Party","organisation":"Fulham Labour Party","detail":"He joined the Fulham Labour Party in 1983.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"politics","start":"1986-05","end":"1986-05","title":"Elected councillor for Gibbs Green ward","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was elected as a Labour councillor for Gibbs Green ward on 8 May 1986.","source":{"title":"London Borough Council Elections May 1986 (London Residuary Body)","url":"https://data.london.gov.uk/download/24r9z/860bbb06-09d8-4f3f-bd84-b60e442a61e8/LBCE_1986-5-8.pdf"}},{"phase":"politics","start":"1986","end":"2005","title":"Councillor","organisation":"Hammersmith and Fulham London Borough Council","detail":"He served as a Labour councillor on Hammersmith and Fulham London Borough Council from 1986 to 2005.","source":{"title":"Andy Slaughter, Politics.co.uk","url":"https://www.politics.co.uk/people/andy-slaughter/"}},{"phase":"politics","start":"1990-05","end":"1990-05","title":"Reelected councillor for Gibbs Green ward","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was reelected as a Labour councillor for Gibbs Green ward on 3 May 1990.","source":{"title":"London Borough Council Elections May 1990 (London Research Centre)","url":"https://data.london.gov.uk/download/24r9z/afda4d3b-5211-4410-886a-16af9d569c8c/LBCE_1990-5-3.pdf"}},{"phase":"politics","start":"1991","end":null,"title":"Deputy Leader","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was elected Deputy Leader of the council in 1991.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}},{"phase":"politics","start":"1994-05","end":"1994-05","title":"Reelected councillor for Gibbs Green ward","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was reelected as a Labour councillor for Gibbs Green ward on 5 May 1994.","source":{"title":"London Borough Council Elections May 1994 (London Research Centre)","url":"https://data.london.gov.uk/download/24r9z/8a8faadf-3660-4617-864c-f4aa683f20e8/LBCE_1994-5-5.pdf"}},{"phase":"politics","start":"1996","end":"2005","title":"Leader of the Council","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was leader of the council from 1996 until 2005.","source":{"title":"Andy Slaughter, Politics.co.uk","url":"https://www.politics.co.uk/people/andy-slaughter/"}},{"phase":"politics","start":"1997-07","end":"1997-07","title":"Labour candidate, Uxbridge byelection","organisation":null,"detail":"He stood unsuccessfully in the Uxbridge byelection on 31 July 1997.","source":{"title":"Andy Slaughter, Politics.co.uk","url":"https://www.politics.co.uk/people/andy-slaughter/"}},{"phase":"politics","start":"1998-05","end":"1998-05","title":"Reelected councillor for Gibbs Green ward","organisation":"Hammersmith and Fulham London Borough Council","detail":"He was reelected as a Labour councillor for Gibbs Green ward on 7 May 1998.","source":{"title":"London Borough Council Elections May 1998 (London Research Centre)","url":"https://data.london.gov.uk/download/2db834ff-edbe-4433-9a9f-438bd585e3c6/6559d43c-4ea0-4b58-b705-94f84c3a549a/LBCE_1998-5-7.pdf"}},{"phase":"politics","start":"2002","end":"2005","title":"Councillor for North End ward","organisation":"Hammersmith and Fulham London Borough Council","detail":"From 2002 he was councillor for North End ward in West Kensington, stepping down in 2005 when elected as an MP.","source":{"title":"About: Andy Slaughter MP","url":"https://andyslaughter.co.uk/about/"}}]$bt$::jsonb::text)),
  (1521, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Greenwell Junior High School","organisation":"Greenwell Junior High School","detail":"She was educated at Greenwell Junior High School.","source":{"title":"Wikipedia: Sharon Hodgson","url":"https://en.wikipedia.org/wiki/Sharon_Hodgson"}},{"phase":"education","start":null,"end":null,"title":"Eight O levels","organisation":"Heathfield Senior High School","detail":"She gained eight O levels and went into the sixth form at Heathfield Senior High School, leaving a few weeks later to start work.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"education","start":null,"end":null,"title":"Newcastle College","organisation":"Newcastle College","detail":"She attended Newcastle College.","source":{"title":"Sharon Hodgson, Politics.co.uk","url":"https://www.politics.co.uk/people/sharon-hodgson/"}},{"phase":"education","start":null,"end":null,"title":"TUC Academy","organisation":"Trades Union Congress","detail":"She attended the Trades Union Congress Academy in London.","source":{"title":"Wikipedia: Sharon Hodgson","url":"https://en.wikipedia.org/wiki/Sharon_Hodgson"}},{"phase":"career","start":null,"end":null,"title":"Accounts clerk","organisation":null,"detail":"She started work as an accounts clerk with a company in the Team Valley.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"career","start":null,"end":null,"title":"Staff member","organisation":"Northern Rock","detail":"She worked for Northern Rock in Gosforth.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"career","start":null,"end":null,"title":"Payroll administrator","organisation":null,"detail":"She returned to the Team Valley as a payroll administrator.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"career","start":"1999","end":"2002","title":"Labour Party organiser","organisation":"Labour Party","detail":"She was a Labour Party organiser from 1999 to 2002.","source":{"title":"Sharon Hodgson, Politics.co.uk","url":"https://www.politics.co.uk/people/sharon-hodgson/"}},{"phase":"career","start":"2001","end":null,"title":"Organiser, Mitcham and Morden","organisation":"Labour Party","detail":"In 2001 she joined Siobhain McDonagh's team in Mitcham and Morden.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"career","start":null,"end":null,"title":"Charity worker","organisation":"Total Learning Challenge","detail":"She worked for the charity Total Learning Challenge.","source":{"title":"Sharon Hodgson, Politics.co.uk","url":"https://www.politics.co.uk/people/sharon-hodgson/"}},{"phase":"career","start":"2002","end":"2005","title":"Labour Link Coordinator","organisation":"UNISON","detail":"From 2002 to 2005 she was the Labour link coordinator for the trade union UNISON.","source":{"title":"Sharon Hodgson, Politics.co.uk","url":"https://www.politics.co.uk/people/sharon-hodgson/"}},{"phase":"politics","start":"1997","end":"1997","title":"Campaign volunteer, South Stockton","organisation":"Labour Party","detail":"She joined the party and volunteered for the 1997 election campaign in the South Stockton seat.","source":{"title":"Westminster dream of a working class girl, The Northern Echo","url":"https://www.thenorthernecho.co.uk/news/6985529.westminster-dream-working-class-girl/"}},{"phase":"politics","start":"1998","end":null,"title":"W