  (1533, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Northwich County Grammar School for Girls","organisation":"Northwich County Grammar School for Girls","detail":"She attended Northwich County Grammar School for Girls.","source":{"title":"Dame Diana Johnson, Politics.co.uk","url":"https://www.politics.co.uk/people/dame-diana-johnson/"}},{"phase":"education","start":"1982","end":"1984","title":"Sixth form: history, English and economics","organisation":"Sir John Deane's College","detail":"She studied history, English and economics at Sir John Deane's College from 1982 to 1984.","source":{"title":"Wikipedia: Diana Johnson","url":"https://en.wikipedia.org/wiki/Diana_Johnson"}},{"phase":"education","start":null,"end":null,"title":"LLB Law","organisation":"Queen Mary University of London","detail":"She gained an LLB in Law from Queen Mary University of London.","source":{"title":"Dame Diana Johnson, Politics.co.uk","url":"https://www.politics.co.uk/people/dame-diana-johnson/"}},{"phase":"career","start":"1991","end":"1991","title":"Became a barrister","organisation":null,"detail":"She became a barrister in 1991.","source":{"title":"Dame Diana Johnson, Politics.co.uk","url":"https://www.politics.co.uk/people/dame-diana-johnson/"}},{"phase":"career","start":null,"end":null,"title":"Barrister, community law centres","organisation":null,"detail":"She qualified as a barrister and worked for many years in community law centres.","source":{"title":"About Diana, Diana Johnson MP","url":"https://www.dianajohnson.co.uk/about"}},{"phase":"career","start":"1999","end":"2005","title":"Barrister","organisation":"Paddington Law Centre","detail":"She was a barrister at Paddington Law Centre from 1999 to 2005.","source":{"title":"Wikipedia: Diana Johnson","url":"https://en.wikipedia.org/wiki/Diana_Johnson"}},{"phase":"career","start":null,"end":null,"title":"Non executive director","organisation":"NHS","detail":"She served as a non executive director in the NHS befor